// The bundle imports "node-fetch" only where `window` is absent, expecting the
// runtime to supply it: Bun's built-in "node-fetch" is a re-export of its native
// fetch. Node >= 18 has a native WHATWG fetch, so this re-exports Node's, the same
// way. Nothing here is emulated; every export is the runtime's own implementation.
const { fetch, Headers, Request, Response, FormData, Blob, File } = globalThis;
export default fetch;
export { fetch, Headers, Request, Response, FormData, Blob, File };
